{"content": "///|
/// A cursor that walks through a TOML input string.
struct Cursor {
  input : String
  mut pos : Int
}

///|
fn Cursor::new(input : String) -> Cursor {
  { input, pos: 0 }
}

///|
/// Return the current character, or `None` at EOF.
fn Cursor::peek(self : Cursor) -> Char? {
  self.input.get_char(self.pos)
}

///|
/// Advance one character and return it, or `None` at EOF.
fn Cursor::next(self : Cursor) -> Char? {
  let ch = self.input.get_char(self.pos)
  match ch {
    Some(_) => {
      let _ : Unit = { self.pos += 1 }
    }
    _ => ()
  }
  ch
}

///|
/// Skip whitespace (spaces and tabs) but not newlines.
fn Cursor::skip_ws(self : Cursor) -> Unit {
  while self.peek() is Some(' ' | '\t') {
    let _ = self.next()
  }
}

///|
/// Skip a comment line starting with `#` (including the newline).
/// Caller ensures current char is `#`.
fn Cursor::skip_comment(self : Cursor) -> Unit {
  // skip until newline or EOF
  while self.peek() is Some(ch) && ch != '\n' {
    let _ = self.next()
  }
}

///|
/// Skip whitespace and comments until the next significant character.
fn Cursor::skip_blank(self : Cursor) -> Unit {
  while true {
    match self.peek() {
      Some(' ' | '\t' | '\n' | '\r') => {
        let _ = self.next()
      }
      Some('#') => self.skip_comment()
      _ => break ()
    }
  }
}

///|
/// Return the current 0-based position.
fn Cursor::position(self : Cursor) -> Int {
  self.pos
}
