{"content": "///|
/// Parse a complete TOML document into a `Json` value.
pub fn parse_toml(input : String) -> Json raise ParseError {
  let c = Cursor::new(input)
  let root : Map[String, Json] = {}
  parse_table(c, "", root)
  Json::object(root)
}

///|
/// Internal: parse key-value pairs and nested tables until EOF.
/// `prefix` is the current dotted table path (e.g. `"database.settings"`).
/// `into` is the map to populate *at the current table level*.
fn parse_table(
  c : Cursor,
  prefix : String,
  into : Map[String, Json],
) -> Unit raise ParseError {
  loop {
    c.skip_blank()
    match c.peek() {
      None => break
      Some('[') => {
        let _ = c.next()
        let is_array = c.peek() is Some('[')
        if is_array {
          // skip second `[`
          let _ = c.next()
        }
        c.skip_ws()
        let key = parse_bare_key(c)
        // Check for dotted sub-keys in header, e.g. [a.b.c]
        let full_key = key
        c.skip_ws()
        if is_array {
          if c.peek() is Some(']') {
            let _ = c.next()
          } else {
            raise ExpectedCloseBracket(c.position())
          }
        }
        if c.peek() is Some(']') {
          let _ = c.next()
        } else {
          raise ExpectedCloseBracket(c.position())
        }
        if is_array {
          // Skip [[array-of-tables]] for now - we don't fully support it
          // but we can treat it like a regular table
          raise parse_error("Array of tables not yet supported")
        }
        // Enter sub-table
        let new_prefix = if prefix == "" { full_key } else { "\{prefix}.\{full_key}" }
        let sub : Map[String, Json] = {}
        parse_table(c, new_prefix, sub)
        set_nested(into, full_key, Json::object(sub))
      }
      _ => {
        // Key-value pair
        let key = parse_key(c, into)
        c.skip_ws()
        if c.peek() is Some('=') {
          let _ = c.next()
        } else {
          raise ExpectedEquals(c.position())
        }
        c.skip_ws()
        let value = parse_value(c)
        // Resolve dotted key
        let full_key = if prefix == "" { key } else { "\{prefix}.\{key}" }
        set_nested(into, key, value)
        c.skip_blank()
        // Optional newline after value
        if c.peek() is Some('\n' | '\r') {
          let _ = c.next()
        }
      }
    }
  }
}

///|
/// Set a (possibly dotted) key in a nested map.
/// e.g. `set_nested(m, "a.b.c", v)` creates `{"a": {"b": {"c": v}}}`.
fn set_nested(
  into : Map[String, Json],
  key : String,
  value : Json,
) -> Unit raise ParseError {
  let parts = split_dot(key)
  if parts.length() <= 1 {
    if into.contains(key) {
      raise DuplicateKey(key)
    }
    into[key] = value
    return
  }
  // Walk dotted key segments
  let mut cur = into
  for i = 0; i < parts.length() - 1; i = i + 1 {
    let seg = parts[i]
    if cur.contains(seg) {
      match cur[seg] {
        Json::Object(_) => {
          // already a table, keep going
        }
        _ => raise DuplicateKey(seg)
      }
    } else {
      cur[seg] = Json::object({})
    }
    // re-fetch the inner map reference
    cur = match cur[seg] {
      Json::Object(inner) => inner
      _ => { raise DuplicateKey(seg) }
    }
  }
  let last = parts[parts.length() - 1]
  if cur.contains(last) {
    raise DuplicateKey(key)
  }
  cur[last] = value
}

///|
/// Split a string by `.`, returning parts.
fn split_dot(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut start = 0
  for i = 0; i < s.length(); i = i + 1 {
    if s[i] == '.' as UInt16 {
      let part = s[start:i].to_owned()
      parts.push(part)
      start = i + 1
    }
  }
  parts.push(s[start:].to_owned())
  parts
}

///|
/// Parse a key (bare or dotted), checking for duplicates.
/// Returns the full key string (may contain dots).
fn parse_key(c : Cursor, into : Map[String, Json]) -> String raise ParseError {
  c.skip_ws()
  let key = parse_bare_key(c)
  // Check for dots in the key itself
  c.skip_ws()
  // Dotted keys span across bare-key dot bare-key ...
  loop {
    if c.peek() is Some('.') {
      let _ = c.next()
      c.skip_ws()
      let rest = parse_bare_key(c)
      // Append to key
      key += "."
      key += rest
      c.skip_ws()
    } else {
      break
    }
  }
  key
}

///|
/// Parse a bare key: alphanumeric, underscore, or dash.
fn parse_bare_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  let sb = StringBuilder()
  match c.peek() {
    Some('"' | '\'') => return parse_string(c)
    Some(ch) if ch.is_alphanumeric() || ch == '_' || ch == '-' => {
      sb.write_char(ch)
      let _ = c.next()
    }
    Some(ch) => raise UnexpectedChar(c.position(), ch)
    None => raise ExpectedValue(c.position())
  }
  loop {
    match c.peek() {
      Some(ch) if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '.' => {
        if ch == '.' {
          break
        }
        sb.write_char(ch)
        let _ = c.next()
      }
      _ => break
    }
  }
  sb.to_string()
}

///|
/// Parse a TOML value: string, integer, boolean, array.
fn parse_value(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"') | Some('\'') => parse_string(c)
    Some('[') => parse_array(c)
    Some('t' | 'f') => parse_bool(c)
    Some(ch) if ch.is_digit() || ch == '-' || ch == '+' => parse_number(c)
    Some(ch) => raise UnexpectedChar(c.position(), ch)
    None => raise ExpectedValue(c.position())
  }
}

///|
/// Parse a string value, supporting basic escapes: `\\`, `\"`, `\n`, `\t`.
fn parse_string(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let delim = match c.next() {
    Some(d) if d == '"' || d == '\'' => d
    _ => raise ExpectedValue(c.position())
  }
  let sb = StringBuilder()
  loop {
    match c.next() {
      None => raise UnterminatedString(c.position())
      Some(ch) =>
        if ch == delim {
          break
        } else if ch == '\\' {
          match c.next() {
            None => raise UnterminatedString(c.position())
            Some('"') => sb.write_char('"')
            Some('\\') => sb.write_char('\\')
            Some('n') => sb.write_char('\n')
            Some('t') => sb.write_char('\t')
            Some('r') => sb.write_char('\r')
            Some(other) => {
              let seq = "\\"
              seq += other.to_string()
              raise InvalidEscape(c.position(), seq)
            }
          }
        } else {
          sb.write_char(ch)
        }
    }
  }
  Json::string(sb.to_string())
}

///|
/// Parse a boolean literal: `true` or `false`.
fn parse_bool(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  match c.peek() {
    Some('t') => {
      let _ = c.next()
      if c.next() is Some('r') && c.next() is Some('u') && c.next() is Some('e') {
        return Json::boolean(true)
      }
      raise InvalidNumber(pos, "true")
    }
    Some('f') => {
      let _ = c.next()
      if c.next() is Some('a') && c.next() is Some('l') && c.next() is Some('s') && c.next() is Some('e') {
        return Json::boolean(false)
      }
      raise InvalidNumber(pos, "false")
    }
    _ => raise ExpectedValue(c.position())
  }
}

///|
/// Parse an integer (decimal only, no floats for now).
fn parse_number(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  let sb = StringBuilder()
  match c.peek() {
    Some('-' | '+') => {
      sb.write_char(c.next().unwrap())
    }
    _ => ()
  }
  if c.peek() is None || not(c.peek().unwrap().is_digit()) {
    raise InvalidNumber(pos, sb.to_string())
  }
  loop {
    match c.peek() {
      Some(ch) if ch.is_digit() => {
        sb.write_char(ch)
        let _ = c.next()
      }
      _ => break
    }
  }
  let s = sb.to_string()
  // We'll store as Json::number from Double for now; integers are represented as numbers.
  // Try to parse as Int64
  let i = parse_int64_opt(s)
  match i {
    Some(val) => Json::number(val.to_double())
    None => raise InvalidNumber(pos, s)
  }
}

///|
/// Parse an array: `[value, value, ...]`.
fn parse_array(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  if c.peek() is Some('[') {
    let _ = c.next()
  } else {
    raise ExpectedValue(c.position())
  }
  c.skip_ws()
  let arr : Array[Json] = []
  // Empty array
  if c.peek() is Some(']') {
    let _ = c.next()
    return Json::array(arr)
  }
  loop {
    c.skip_ws()
    let val = parse_value(c)
    arr.push(val)
    c.skip_ws()
    match c.peek() {
      Some(',') => {
        let _ = c.next()
        c.skip_ws()
        // Trailing comma allowed
        if c.peek() is Some(']') {
          let _ = c.next()
          break
        }
      }
      Some(']') => {
        let _ = c.next()
        break
      }
      Some(ch) => raise UnexpectedChar(c.position(), ch)
      None => raise ExpectedCloseBracket(c.position())
    }
  }
  Json::array(arr)
}

///|
/// Try to parse a string as Int64, returning None on failure.
fn parse_int64_opt(s : String) -> Int64? {
  try {
    // Simple case: use @strconv
    let val = parse_int64_simple(s)
    Some(val)
  } catch {
    _ => None
  } noraise {
    _ => None
  }
}

///|
fn parse_int64_simple(s : String) -> Int64 {
  let neg = s[0] == '-' as UInt16
  let start = if neg { 1 } else { 0 }
  let mut val : Int64 = 0
  for i = start; i < s.length(); i = i + 1 {
    let d = (s[i] - '0' as UInt16).to_int64()
    val = val * 10 + d
  }
  if neg {
    -val
  } else {
    val
  }
}
