///|
/// Parse a bare key: alphanumeric, underscore, or dash.
fn parse_bare_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  let sb = StringBuilder()
  match c.peek() {
    Some('"' | '\'') => return parse_string(c)
    Some(ch) if ch.is_alphanumeric() || ch == '_' || ch == '-' => {
      sb.write_char(ch)
      let _ = c.next()
    }
    Some(ch) => raise UnexpectedChar(c.position(), ch)
    None => raise ExpectedValue(c.position())
  }
  loop {
    match c.peek() {
      Some(ch) if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '.' => {
        if ch == '.' {
          break
        }
        sb.write_char(ch)
        let _ = c.next()
      }
      _ => break
    }
  }
  sb.to_string()
}

///|
/// Parse a TOML value: string, integer, boolean, array.
fn parse_value(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"') | Some('\'') => parse_string(c)
    Some('[') => parse_array(c)
    Some('t' | 'f') => parse_bool(c)
    Some(ch) if ch.is_digit() || ch == '-' || ch == '+' => parse_number(c)
    Some(ch) => raise UnexpectedChar(c.position(), ch)
    None => raise ExpectedValue(c.position())
  }
}

///|
/// Parse a string value, supporting basic escapes: `\\`, `\"`, `\n`, `\t`.
fn parse_string(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let delim = match c.next() {
    Some(d) if d == '"' || d == '\'' => d
    _ => raise ExpectedValue(c.position())
  }
  let sb = StringBuilder()
  loop {
    match c.next() {
      None => raise UnterminatedString(c.position())
      Some(ch) =>
        if ch == delim {
          break
        } else if ch == '\\' {
          match c.next() {
            None => raise UnterminatedString(c.position())
            Some('"') => sb.write_char('"')
            Some('\\') => sb.write_char('\\')
            Some('n') => sb.write_char('\n')
            Some('t') => sb.write_char('\t')
            Some('r') => sb.write_char('\r')
            Some(other) => {
              let seq = "\\"
              seq += other.to_string()
              raise InvalidEscape(c.position(), seq)
            }
          }
        } else {
          sb.write_char(ch)
        }
    }
  }
  Json::string(sb.to_string())
}

///|
/// Parse a boolean literal: `true` or `false`.
fn parse_bool(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  match c.peek() {
    Some('t') => {
      let _ = c.next()
      if c.next() is Some('r') && c.next() is Some('u') && c.next() is Some('e') {
        return Json::boolean(true)
      }
      raise InvalidNumber(pos, "true")
    }
    Some('f') => {
