/// Parse a complete TOML document into a `Json` value.
pub fn parse_toml(input : String) -> Json raise ParseError {
  let c = Cursor::new(input)
  let root : Map[String, Json] = {}
  parse_table(c, root)
  Json::object(root)
}

///|
/// Internal: parse key-value pairs and nested tables until EOF.
fn parse_table(c : Cursor, into : Map[String, Json]) -> Unit raise ParseError {
  while true {
    c.skip_blank()
    match c.peek() {
      None => break
      Some('[') => {
        let _ = c.next()
        let is_array = c.peek() is Some('[')
        if is_array {
          let _ = c.next()
        }
        c.skip_ws()
        let key = parse_bare_key(c)
        c.skip_ws()
        if is_array {
          match c.peek() {
            Some(']') => {
              let _ = c.next()
            }
            _ => raise ExpectedCloseBracket(c.position())
          }
        }
        match c.peek() {
          Some(']') => {
            let _ = c.next()
          }
          _ => raise ExpectedCloseBracket(c.position())
        }
        if is_array {
          raise parse_error("Array of tables not yet supported")
        }
        let sub : Map[String, Json] = {}
        parse_table(c, sub)
        set_nested(into, key, Json::object(sub))
      }
      _ => {
        let key = parse_key(c)
        c.skip_ws()
        match c.peek() {
          Some('=') => {
            let _ = c.next()
          }
          _ => raise ExpectedEquals(c.position())
        }
        c.skip_ws()
        let value = parse_value(c)
        set_nested(into, key, value)
        c.skip_blank()
        match c.peek() {
          Some('\n' | '\r') => {
            let _ = c.next()
          }
          _ => ()
        }
      }
    }
  }
}

///|
/// Set a (possibly dotted) key in a nested map, detecting duplicate keys.
fn set_nested(
  into : Map[String, Json],
  key : String,
  value : Json,
) -> Unit raise ParseError {
  let parts = split_dot(key)
  set_nested_parts(into, parts, 0, value, key)
}

///|
/// Recursively walk dotted key parts.
fn set_nested_parts(
  into : Map[String, Json],
  parts : Array[String],
  idx : Int,
  value : Json,
  full_key : String,
) -> Unit raise ParseError {
  let seg = parts[idx]
  if idx == parts.length() - 1 {
    if into.contains(seg) {
      raise DuplicateKey(full_key)
    }
    into[seg] = value
  } else {
    if into.contains(seg) {
      // Navigate into existing nested object
      let child = into[seg]
      match child {
        Json::Object(inner) => {
          set_nested_parts(inner, parts, idx + 1, value, full_key)
        }
        _ => raise DuplicateKey(seg)
      }
    } else {
      let sub : Map[String, Json] = {}
      into[seg] = Json::object(sub)
      set_nested_parts(sub, parts, idx + 1, value, full_key)
    }
  }
}

///|
/// Split a string by `.`, returning parts.
fn split_dot(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut start = 0
  for i = 0; i < s.length(); i = i + 1 {
    let ch : UInt16 = s[i]
    if ch == '.' {
      let part = s[start:i]
      parts.push(part.to_owned())
      start = i + 1
    }
  }
  parts.push(s[start:].to_string())
  parts
}

///|
/// Parse a key (bare or dotted).
fn parse_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  let key = parse_bare_key(c)
  let mut full = key
  c.skip_ws()
  while c.peek() is Some('.') {
    let _ = c.next()
    c.skip_ws()
    let rest = parse_bare_key(c)
    full += "."
    full += rest
    c.skip_ws()
  }
  full
}

///|
/// Parse a bare key: alphanumeric, underscore, or dash, or quoted.
fn parse_bare_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"' | '\'') => {
      let j = parse_string(c)
      match j {
        Json::String(s) => s
        _ => raise ExpectedValue(c.position())
      }
    }
    Some(ch) => {
      let sb = StringBuilder()
      sb.write_char(ch)
      let _ = c.next()
      while c.peek() is Some(cur_ch) &&
        (cur_ch.is_alphanumeric() || cur_ch == '_' || cur_ch == '-')
      {
        sb.write_char(cur_ch)
        let _ = c.next()
      }
      sb.to_string()
    }
    None => raise ExpectedValue(c.position())
    _other => raise UnexpectedChar(c.position(), _other)
  }
}

///|
/// Parse a TOML value.
fn parse_value(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"') | Some('\'') => parse_string(c)
    Some('[') => parse_array(c)
    Some('t' | 'f') => parse_bool(c)
    Some(ch) =>
      if ch.is_digit() || ch == '-' || ch == '+' {
        parse_number(c)
      } else {
        raise UnexpectedChar(c.position(), ch)
      }
    None => raise ExpectedValue(c.position())
  }
}

///|
/// Parse a string value, supporting escapes: `\\`, `\"`, `\n`, `\t`.
fn parse_string(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let delim = match c.next() {
    Some(d) if d == '"' || d == '\'' => d
    _ => raise ExpectedValue(c.position())
  }
  let sb = StringBuilder()
  while true {
    match c.next() {
      None => raise UnterminatedString(c.position())
      Some(ch) =>
        if ch == delim {
          break
        } else if ch == '\\' {
          match c.next() {
            None => raise UnterminatedString(c.position())
            Some('"') => sb.write_char('"')
            Some('\\') => sb.write_char('\\')
            Some('n') => sb.write_char('\n')
            Some('t') => sb.write_char('\t')
            Some('r') => sb.write_char('\r')
            Some(other) => {
              let mut seq = "\\"
              seq += other.to_string()
              raise InvalidEscape(c.position(), seq)
            }
          }
        } else {
          sb.write_char(ch)
        }
    }
  }
  Json::string(sb.to_string())
}

///|
/// Parse a boolean literal.
fn parse_bool(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  match c.peek() {
    Some('t') => {
      let _ = c.next()
      if c.next() is Some('r') && c.next() is Some('u') && c.next() is Some('e') {
        return Json::boolean(true)
      }
      raise InvalidNumber(pos, "true")
    }
    Some('f') => {
      let _ = c.next()
      if c.next() is Some('a') && c.next() is Some('l') && c.next() is Some('s') && c.next() is Some('e') {
        return Json::boolean(false)
      }
      raise InvalidNumber(pos, "false")
    }
    _ => raise ExpectedValue(c.position())
  }
}

///|
/// Parse an integer (decimal only).
fn parse_number(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  let sb = StringBuilder()
  match c.peek() {
    Some('-' | '+') => {
      let ch = c.next().unwrap()
      sb.write_char(ch)
    }
    _ => ()
  }
  match c.peek() {
    None => raise InvalidNumber(pos, sb.to_string())
    Some(ch) =>
      if ch.is_digit() {
        sb.write_char(ch)
        let _ = c.next()
      } else {
        raise InvalidNumber(pos, sb.to_string())
      }
  }
  while c.peek() is Some(ch) && ch.is_digit() {
    sb.write_char(ch)
    let _ = c.next()
  }
  let s = sb.to_string()
  let i = parse_int64_opt(s)
  match i {
    Some(val) => Json::number(val.to_double())
    None => raise InvalidNumber(pos, s)
  }
}

///|
/// Parse an array: `[value, value, ...]`.
fn parse_array(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  if c.peek() is Some('[') {
    let _ = c.next()
  } else {
    raise ExpectedValue(c.position())
  }
  c.skip_ws()
  let arr : Array[Json] = []
  if c.peek() is Some(']') {
    let _ = c.next()
    return Json::array(arr)
  }
  while true {
    c.skip_ws()
    let val = parse_value(c)
    arr.push(val)
    c.skip_ws()
    match c.peek() {
      Some(',') => {
        let _ = c.next()
        c.skip_ws()
        if c.peek() is Some(']') {
          let _ = c.next()
          break
        }
      }
      Some(']') => {
        let _ = c.next()
        break
      }
      Some(ch) => raise UnexpectedChar(c.position(), ch)
      None => raise ExpectedCloseBracket(c.position())
    }
  }
  Json::array(arr)
}

///|
/// Try to parse a string as Int64, returning None on failure.
fn parse_int64_opt(s : String) -> Int64? {
  if s == "" {
    return None
  }
  let neg_overload : UInt16 = '-'
  let neg = s[0] == neg_overload
  let start = if neg { 1 } else { 0 }
  if start >= s.length() {
    return None
  }
  let mut val : Int64 = 0
  let zero_overload : UInt16 = '0'
  let nine_overload : UInt16 = '9'
  for i = start; i < s.length(); i = i + 1 {
    let ch = s[i]
    if ch < zero_overload || ch > nine_overload {
      return None
    }
    let d = (ch - zero_overload).to_int64()
    val = val * 10 + d
  }
  if neg {
    Some(-val)
  } else {
    Some(val)
  }
}
