///|
/// Error type for TOML parsing failures.
pub(all) suberror ParseError {
  /// Unexpected character at the given position.
  UnexpectedChar(Int, Char)
  /// A key was defined more than once.
  DuplicateKey(String)
  /// Unterminated string literal.
  UnterminatedString(Int)
  /// Invalid escape sequence in a string.
  InvalidEscape(Int, String)
  /// Expected a value but found something else.
  ExpectedValue(Int)
  /// Expected `= ` after a key.
  ExpectedEquals(Int)
  /// Expected `]` to close a table header or array.
  ExpectedCloseBracket(Int)
  /// Invalid number format.
  InvalidNumber(Int, String)
  /// A table header appeared after a key-value pair at the same level
  /// (or the same table was redefined).
  TableRedefinition(String)
  /// Generic parse failure with a message.
  Generic(String)
} derive(Eq, ToJson, Debug)

