/// Resolve a dotted key path and return the innermost Json value.
fn resolve_nested(root : Map[String, Json], key : String) -> Json {
  let parts = split_dot(key)
  let mut cur : Json = Json::object(root)
  for i = 0; i < parts.length(); i = i + 1 {
