{"content": "///|
/// Parse a complete TOML document into a `Json` value.
pub fn parse_toml(input : String) -> Json raise ParseError {
  let c = Cursor::new(input)
  let root : Map[String, Json] = {}
  parse_table(c, root)
  Json::object(root)
}

///|
/// Internal: parse key-value pairs and nested tables until EOF.
/// `into` is the current table map where key-values are placed.
fn parse_table(c : Cursor, into : Map[String, Json]) -> Unit raise ParseError {
  while true {
    c.skip_blank()
    match c.peek() {
      None => break
      Some('[') => {
        let _ = c.next()
        let is_array = c.peek() is Some('[')
        if is_array {
          let _ = c.next()
        }
        c.skip_ws()
        let key = parse_table_key(c)
        c.skip_ws()
        if is_array {
          match c.peek() {
            Some(']') => {
              let _ = c.next()
            }
            _ => raise ExpectedCloseBracket(c.position())
          }
        }
        match c.peek() {
          Some(']') => {
            let _ = c.next()
          }
          _ => raise ExpectedCloseBracket(c.position())
        }
        if is_array {
          raise parse_error("Array of tables not yet supported")
        }
        // Table header: ensure the path exists in the root map and parse into it
        let sub = ensure_table_at(into, key, is_first=true)
        parse_table(c, sub)
      }
      _ => {
        let key = parse_key(c)
        c.skip_ws()
        match c.peek() {
          Some('=') => {
            let _ = c.next()
          }
          _ => raise ExpectedEquals(c.position())
        }
        c.skip_ws()
        let value = parse_value(c)
        set_nested(into, key, value)
        c.skip_blank()
        match c.peek() {
          Some('\n' | '\r') => {
            let _ = c.next()
          }
          _ => ()
        }
      }
    }
  }
}

///|
/// Ensure a dotted key path exists as nested maps within `base`.
/// `is_first` means we are at the top level and `base` is the root map.
/// Returns the innermost map.
fn ensure_table_at(
  base : Map[String, Json],
  key : String,
  is_first : Bool,
) -> Map[String, Json] raise ParseError {
  let parts = split_dot(key)
  // Navigate from base
  let mut cur = base
  for i = 0; i < parts.length() - 1; i = i + 1 {
    let seg = parts[i]
    if cur.contains(seg) {
      match cur[seg] {
        Json::Object(inner) => cur = inner
        _ => raise DuplicateKey(seg)
      }
    } else {
      let sub : Map[String, Json] = {}
      cur[seg] = Json::object(sub)
      cur = sub
    }
  }
  let last = parts[parts.length() - 1]
  if cur.contains(last) {
    match cur[last] {
      Json::Object(inner) => {
        // Table already exists; parse into it (merge mode).
        // However, redefining a table after it already has keys is allowed
        // only if no prior [table] was completed with a newline and a new
        // [table] header. For simplicity, we allow re-entering a table.
        return inner
      }
      _ => raise DuplicateKey(last)
    }
  }
  let sub : Map[String, Json] = {}
  cur[last] = Json::object(sub)
  sub
}

///|
/// Set a (possibly dotted) key in a nested map, detecting duplicate keys.
fn set_nested(
  into : Map[String, Json],
  key : String,
  value : Json,
) -> Unit raise ParseError {
  let parts = split_dot(key)
  set_nested_parts(into, parts, 0, value, key)
}

///|
/// Recursively walk dotted key parts.
fn set_nested_parts(
  into : Map[String, Json],
  parts : Array[String],
  idx : Int,
  value : Json,
  full_key : String,
) -> Unit raise ParseError {
  let seg = parts[idx]
  if idx == parts.length() - 1 {
    if into.contains(seg) {
      raise DuplicateKey(full_key)
    }
    into[seg] = value
  } else {
    if into.contains(seg) {
      let child = into[seg]
      match child {
        Json::Object(inner) => {
          set_nested_parts(inner, parts, idx + 1, value, full_key)
        }
        _ => raise DuplicateKey(seg)
      }
    } else {
      let sub : Map[String, Json] = {}
      into[seg] = Json::object(sub)
      set_nested_parts(sub, parts, idx + 1, value, full_key)
    }
  }
}

///|
/// Split a string by `.`, returning parts.
fn split_dot(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut start = 0
  for i = 0; i < s.length(); i = i + 1 {
    let ch : UInt16 = s[i]
    if ch == '.' {
      let part = s[start:i]
      parts.push(part.to_owned())
      start = i + 1
    }
  }
  parts.push(s[start:].to_owned())
  parts
}

///|
/// Parse a key (bare or dotted).
fn parse_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  let key = parse_bare_key(c)
  let mut full = key
  c.skip_ws()
  while c.peek() is Some('.') {
    let _ = c.next()
    c.skip_ws()
    let rest = parse_bare_key(c)
    full += "."
    full += rest
    c.skip_ws()
  }
  full
}

///|
/// Parse a key for a table header (may contain dots like `database.settings`).
fn parse_table_key(c : Cursor) -> String raise ParseError {
  parse_key(c)
}

///|
/// Parse a bare key: alphanumeric, underscore, or dash, or quoted.
fn parse_bare_key(c : Cursor) -> String raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"' | '\'') => {
      let j = parse_string(c)
      match j {
        Json::String(s) => s
        _ => raise ExpectedValue(c.position())
      }
    }
    Some(ch) => {
      let sb = StringBuilder()
      sb.write_char(ch)
      let _ = c.next()
      while is_bare_key_char(c.peek()) {
        let cur_ch = c.next().unwrap()
        sb.write_char(cur_ch)
      }
      sb.to_string()
    }
    None => raise ExpectedValue(c.position())
  }
}

///|
/// Parse a TOML value.
fn parse_value(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  match c.peek() {
    Some('"') | Some('\'') => parse_string(c)
    Some('[') => parse_array(c)
    Some('t' | 'f') => parse_bool(c)
    Some(ch) =>
      if ch.is_ascii_digit() || ch == '-' || ch == '+' {
        parse_number(c)
      } else {
        raise UnexpectedChar(c.position(), ch)
      }
    None => raise ExpectedValue(c.position())
  }
}

///|
/// Parse a string value, supporting escapes: `\\`, `\"`, `\n`, `\t`.
fn parse_string(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let delim = match c.next() {
    Some(d) if d == '"' || d == '\'' => d
    _ => raise ExpectedValue(c.position())
  }
  let sb = StringBuilder()
  while true {
    match c.next() {
      None => raise UnterminatedString(c.position())
      Some(ch) =>
        if ch == delim {
          break
        } else if ch == '\\' {
          match c.next() {
            None => raise UnterminatedString(c.position())
            Some('"') => sb.write_char('"')
            Some('\\') => sb.write_char('\\')
            Some('n') => sb.write_char('\n')
            Some('t') => sb.write_char('\t')
            Some('r') => sb.write_char('\r')
            Some(other) => {
              let mut seq = "\\"
              seq += other.to_string()
              raise InvalidEscape(c.position(), seq)
            }
          }
        } else {
          sb.write_char(ch)
        }
    }
  }
  Json::string(sb.to_string())
}

///|
/// Parse a boolean literal.
fn parse_bool(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  match c.peek() {
    Some('t') => {
      let _ = c.next()
      if c.next() is Some('r') && c.next() is Some('u') && c.next() is Some('e') {
        return Json::boolean(true)
      }
      raise InvalidNumber(pos, "true")
    }
    Some('f') => {
      let _ = c.next()
      if c.next() is Some('a') && c.next() is Some('l') && c.next() is Some('s') && c.next() is Some('e') {
        return Json::boolean(false)
      }
      raise InvalidNumber(pos, "false")
    }
    _ => raise ExpectedValue(c.position())
  }
}

///|
/// Parse an integer (decimal only).
fn parse_number(c : Cursor) -> Json raise ParseError {
  c.skip_ws()
  let pos = c.position()
  let sb = StringBuilder()
  match c.peek() {
    Some('-' | '+') => {
      let ch = c.next().unwrap()
      sb.write_char(ch)
    }
    _ => ()
  }
  match c.peek() {
    None => raise InvalidNumber(pos, sb.to_string())
    Some(ch) =>
      if ch.is_ascii_digit() {
        sb.write_char(ch)
        let _ = c.next()
      } else {
        raise InvalidNumber(pos, sb.to_string())
      }
  }
  while c.peek() is Some(ch) && ch.is_ascii_digit() {
