///|
async fn main {
  let cmd = @argparse.Command::new(
    "tomljson",
    flags=[@argparse.FlagArg::new("stdin", long="stdin", about="Read TOML from standard input")],
    positionals=[@argparse.PositionArg::new(
      "file",
      about="Path to a TOML file",
    )],
    about="Convert TOML to JSON",
  )
  let matches = cmd.parse()

  let stdin_flag = matches.flags.get("stdin").unwrap_or(false)
  let file_path = match matches.values.get("file") {
    Some(arr) if arr.length() > 0 => Some(arr[0])
    _ => None
  }

  let input = try {
    if stdin_flag {
      @stdio.stdin.read_all().text()
    } else {
      match file_path {
        Some(path) => @fs.read_file(path).text()
        None => {
          @stdio.stderr.write("Error: Either provide a file path or use --stdin\n")
          return
        }
      }
    }
  } catch {
    err => {
      @stdio.stderr.write("Error: \{err}\n")
      return
    }
  }

  let json = try {
    @toml.parse_toml(input)
  } catch {
    err => {
      @stdio.stderr.write("Error: \{err.to_string()}\n")
      return
    }
  }

  let output = json.stringify()
  @stdio.stdout.write(output)
  @stdio.stdout.write("\n")
}

